import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import DeleteappAdmins from "./DeleteappAdmins.vue";
import { add_and_list_appadmins } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import AddappAdmins from "./AddappAdmins.vue";
export default {
  components: {
    SnackBar,
    AddappAdmins,
    DeleteappAdmins
  },
  props: {
    adminList: Boolean,
    rowInfo: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      SnackBarComponent: {},
      appAdmins: false,
      componentCheck: 0,
      onBoardDialog: false,
      loading: false,
      deleteadmins: false,
      headers: [{
        title: "Email",
        key: "user_email_id",
        sortable: false
      }, {
        title: "Delete",
        key: "action",
        sortable: false
      }],
      tableData: [],
      height: 0,
      tableLoading: false,
      adminitems: {},
      approvalType: "",
      formDetails: {},
      formViewDailog: false,
      fixed: true,
      searchF: "",
      actionItem: "",
      selectTeam: "",
      viewAction: "Inititaie",
      userArray: []
    };
  },
  watch: {
    adminList: {
      async handler() {
        this.selectTeam = "";
        this.$store.commit("Setnamesearch", this.searchF);
        this.height = window.innerHeight - 290;
        await this.adminslist();
        await this.get_all_org_users();
        await this.fetch_details();
      },
      immediate: true
    }
  },
  // created() {
  //    console.log(this.$store.getters.GetAppDetails.dashboard_id);

  // },
  methods: {
    fetch_details() {
      // Clear the array first to prevent duplicates
      this.userArray = [];
      const seenUserIds = new Set();
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE" && element.user_type != "CHATBOT" && !seenUserIds.has(element.user_email_id)) {
          seenUserIds.add(element.user_email_id);
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_email_id
          });
        }
      });
    },
    close_dialog() {
      this.selectTeam = "";
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    async add_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(add_and_list_appadmins, {
            input: {
              action_type: "ADD",
              user_email_id: this.selectTeam.user_id,
              app_id: this.rowInfo.admin_dashboard_id
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.add_and_list_appadmins);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.selectTeam = "";
            this.$refs.form.reset();
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "green",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
            this.adminslist();
          } else {
            this.SnackBarComponent = {
              SnackbarVmodel: true,
              SnackbarColor: "red",
              SnackbarText: response.Message,
              timeout: 5000,
              Top: true
            };
          }
        } catch (error) {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: error.errors[0].message,
            timeout: 5000,
            Top: true
          };
          this.loading = false;
        }
      }
    },
    async adminslist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_and_list_appadmins, {
          input: {
            action_type: "LIST",
            user_email_id: data.user.user_email_id,
            app_id: this.rowInfo.admin_dashboard_id
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.add_and_list_appadmins).data;
        this.tableData = response;
        // console.log(response);
        // console.log(response);
      } catch (error) {
        // console.log(error);
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    add_action() {
      this.componentCheck = 1;
      this.appAdmins = true;
    },
    delete_admins(item) {
      this.adminitems = item;
      this.componentCheck = 2;
      this.deleteadmins = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.appAdmins = false;
      this.deleteadmins = false;
      this.adminslist();
    }
  }
};
